    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script type="text/babel">
      const quizQuestions = [
        {
          id: "q1",
          title: "Which of these are compiled programming languages?",
          helpText: "Select every answer that is generally compiled ahead of time in typical workflows.",
          options: [
            { value: "c-plus-plus", label: "C++", hint: "Commonly compiled to native machine code." },
