        {
          id: "q2",
          title: "Which languages are widely used for web development?",
          options: [
            { value: "html", label: "HTML", hint: "Defines structure for web pages." },
            { value: "css", label: "CSS", hint: "Styles web interfaces and layouts." },
            { value: "sql", label: "SQL", hint: "Queries and manages relational data." },
            { value: "javascript", label: "JavaScript", hint: "Adds interactivity on the client and server." },
          ],
        },
        {
          id: "q3",
          title: "Which of these languages emphasize type safety?",
          options: [
            { value: "typescript", label: "TypeScript", hint: "Adds static typing to JavaScript." },
            { value: "rust", label: "Rust", hint: "Strong compile-time guarantees and ownership checks." },
            { value: "go", label: "Go", hint: "Statically typed with a simple type system." },
            { value: "bash", label: "Bash", hint: "Shell scripting language with dynamic behavior." },
          ],
        },
      ];

      function OptionCard({ questionId, option, checked, onToggle }) {
        return (
          <label className={`option-card ${checked ? "selected" : ""}`}>
            <input
              type="checkbox"
              name={`${questionId}-${option.value}`}
              checked={checked}
              onChange={() => onToggle(questionId, option.value)}
            />
            <span className="option-copy">
              <span className="option-label">{option.label}</span>
              <span className="option-hint">{option.hint}</span>
            </span>
          </label>
        );
      }

      function QuestionField({ question, index, selectedAnswers, onToggle }) {
        return (
          <div className="form-field">
            <div className="question-meta">
              <span className="question-number">{index + 1}</span>
              <h2 className="question-title">{question.title}</h2>
            </div>
            {question.helpText ? <p className="help-text">{question.helpText}</p> : null}
            <div className="options">
              {question.options.map((option) => (
                <OptionCard
                  key={option.value}
                  questionId={question.id}
                  option={option}
                  checked={selectedAnswers.includes(option.value)}
                  onToggle={onToggle}
                />
              ))}
            </div>
          </div>
        );
      }

      function ResultsPanel({ questions, answers }) {
        return (
          <div className="result" aria-live="polite">
            <h2>Selections submitted</h2>
            <p>Your responses are listed below.</p>
