        const toggleAnswer = (questionId, value) => {
          setAnswers((current) => {
            const choices = current[questionId] || [];
            const nextChoices = choices.includes(value)
              ? choices.filter((entry) => entry !== value)
              : [...choices, value];

            return {
              ...current,
              [questionId]: nextChoices,
            };
          });
        };

        const handleSubmit = (event) => {
          event.preventDefault();
          setSubmitted(true);
        };

        return (
          <main className="page-shell">
            <section className="quiz-card">
              <header className="hero">
                <span className="eyebrow">Interactive knowledge check</span>
                <h1>Computer Languages Quiz</h1>
                <p>
                  Explore a short multi-select quiz covering compiled languages, web
                  technologies, and type-safe languages.
                </p>
              </header>

              <form onSubmit={handleSubmit}>
                {quizQuestions.map((question, index) => (
                  <QuestionField
                    key={question.id}
                    question={question}
                    index={index}
                    selectedAnswers={answers[question.id]}
                    onToggle={toggleAnswer}
                  />
                ))}
