              <div className="actions">
                <span className="submit-note">Each question supports multiple answers.</span>
                <button className="submit-button" type="submit" form="">
                  Submit Quiz
                </button>
              </div>

              {submitted ? <ResultsPanel questions={quizQuestions} answers={answers} /> : null}
            </section>
          </main>
        );
      }

      const root = ReactDOM.createRoot(document.getElementById("root"));
      root.render(<QuizApp />);
    </script>
