          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(79, 70, 229, 0.18), transparent 34%),
          radial-gradient(circle at right, rgba(34, 197, 94, 0.14), transparent 28%),
          linear-gradient(180deg, #eef2ff 0%, var(--bg) 38%, #eef4ff 100%);
      }

      .page-shell {
        width: min(900px, calc(100% - 32px));
        margin: 48px auto;
      }

      .quiz-card {
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: 28px;
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
        overflow: hidden;
      }

      .hero {
        padding: 40px 40px 24px;
        background: linear-gradient(135deg, rgba(79, 70, 229, 0.08), rgba(34, 197, 94, 0.06));
        border-bottom: 1px solid rgba(148, 163, 184, 0.18);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: rgba(79, 70, 229, 0.1);
        color: var(--primary);
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.02em;
        text-transform: uppercase;
      }

      h1 {
        margin: 18px 0 10px;
        font-size: clamp(2rem, 4vw, 3.15rem);
        line-height: 1.05;
      }

      .hero p {
        margin: 0;
        max-width: 60ch;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.65;
      }

      form {
        padding: 28px;
      }

      .form-field {
        margin-bottom: 20px;
        padding: 24px;
        border: 1px solid rgba(148, 163, 184, 0.22);
        border-radius: 22px;
        background: rgba(255, 255, 255, 0.85);
      }

      .question-meta {
        display: flex;
        align-items: center;
        gap: 10px;
        margin-bottom: 8px;
      }

      .question-number {
        display: inline-grid;
        place-items: center;
        width: 34px;
        height: 34px;
        border-radius: 50%;
        background: rgba(79, 70, 229, 0.12);
        color: var(--primary);
        font-weight: 700;
      }

      .question-title {
        margin: 0;
        font-size: 1.15rem;
        font-weight: 700;
      }

      .help-text {
        margin: 10px 0 0;
        color: var(--muted);
        font-size: 0.95rem;
        line-height: 1.55;
      }

      .options {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
        gap: 14px;
        margin-top: 18px;
      }

      .option-card {
        display: flex;
        align-items: flex-start;
        gap: 12px;
        padding: 16px;
        border: 1px solid rgba(148, 163, 184, 0.24);
        border-radius: 18px;
        background: #fff;
        cursor: pointer;
        transition: transform 140ms ease, border-color 140ms ease, box-shadow 140ms ease,
          background 140ms ease;
      }

      .option-card:hover {
        transform: translateY(-1px);
        border-color: rgba(79, 70, 229, 0.34);
        box-shadow: 0 14px 30px rgba(79, 70, 229, 0.08);
      }

      .option-card.selected {
        border-color: rgba(79, 70, 229, 0.5);
        background: linear-gradient(180deg, rgba(238, 242, 255, 0.95), #ffffff);
      }

      .option-card input {
        width: 18px;
        height: 18px;
        margin-top: 2px;
        accent-color: var(--primary);
      }

      .option-copy {
        display: grid;
        gap: 4px;
      }

      .option-label {
        font-weight: 600;
      }

      .option-hint {
        color: var(--muted);
        font-size: 0.92rem;
        line-height: 1.4;
      }

      .actions {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        padding: 0 28px 28px;
      }

      .submit-button {
        border: 0;
        border-radius: 14px;
        padding: 14px 22px;
        background: linear-gradient(135deg, var(--primary), var(--primary-dark));
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 16px 32px rgba(79, 70, 229, 0.28);
      }

      .submit-button:hover {
        filter: brightness(1.04);
      }

      .submit-note {
        color: var(--muted);
        font-size: 0.95rem;
      }

      .result {
        margin: 0 28px 28px;
        padding: 20px 22px;
        border-radius: 18px;
        background: rgba(15, 23, 42, 0.04);
        border: 1px solid rgba(148, 163, 184, 0.18);
      }

      .result h2 {
        margin: 0 0 8px;
        font-size: 1.05rem;
      }

      .result p {
        margin: 0 0 14px;
        color: var(--muted);
      }

      .result ul {
        margin: 0;
        padding-left: 18px;
      }

      .result li + li {
        margin-top: 8px;
      }

      @media (max-width: 640px) {
        .page-shell {
          width: min(100% - 20px, 900px);
          margin: 20px auto;
        }

        .hero,
        form,
        .actions,
        .result {
          padding-left: 18px;
          padding-right: 18px;
        }

        .actions {
          align-items: stretch;
          flex-direction: column;
        }

        .submit-button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script crossorigin src="https://unpkg.com/react@18/umd/react.development.js"></script>
    <script crossorigin src="https://unpkg.com/react-dom@18/umd/react-dom.development.js"></script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script type="text/babel">
      const quizQuestions = [
        {
          id: "q1",
          title: "Which of these are compiled programming languages?",
          helpText: "Select every answer that is generally compiled ahead of time in typical workflows.",
          options: [
            { value: "c-plus-plus", label: "C++", hint: "Commonly compiled to native machine code." },
            { value: "javascript", label: "JavaScript", hint: "Usually interpreted or JIT-compiled by engines." },
            { value: "rust", label: "Rust", hint: "Compiled to native binaries with strong safety checks." },
            { value: "python", label: "Python", hint: "Most often executed by an interpreter." },
          ],
        },
        {
          id: "q2",
          title: "Which languages are widely used for web development?",
          options: [
            { value: "html", label: "HTML", hint: "Defines structure for web pages." },
            { value: "css", label: "CSS", hint: "Styles web interfaces and layouts." },
            { value: "sql", label: "SQL", hint: "Queries and manages relational data." },
            { value: "javascript", label: "JavaScript", hint: "Adds interactivity on the client and server." },
          ],
        },
        {
          id: "q3",
          title: "Which of these languages emphasize type safety?",
          options: [
            { value: "typescript", label: "TypeScript", hint: "Adds static typing to JavaScript." },
            { value: "rust", label: "Rust", hint: "Strong compile-time guarantees and ownership checks." },
            { value: "go", label: "Go", hint: "Statically typed with a simple type system." },
            { value: "bash", label: "Bash", hint: "Shell scripting language with dynamic behavior." },
          ],
        },
      ];

      function OptionCard({ questionId, option, checked, onToggle }) {
        return (
          <label className={`option-card ${checked ? "selected" : ""}`}>
            <input
              type="checkbox"
              name={`${questionId}-${option.value}`}
              checked={checked}
              onChange={() => onToggle(questionId, option.value)}
            />
            <span className="option-copy">
              <span className="option-label">{option.label}</span>
              <span className="option-hint">{option.hint}</span>
            </span>
          </label>
        );
      }

      function QuestionField({ question, index, selectedAnswers, onToggle }) {
        return (
          <div className="form-field">
            <div className="question-meta">
              <span className="question-number">{index + 1}</span>
              <h2 className="question-title">{question.title}</h2>
            </div>
            {question.helpText ? <p className="help-text">{question.helpText}</p> : null}
            <div className="options">
              {question.options.map((option) => (
                <OptionCard
                  key={option.value}
                  questionId={question.id}
                  option={option}
                  checked={selectedAnswers.includes(option.value)}
                  onToggle={onToggle}
                />
              ))}
            </div>
          </div>
        );
      }

      function ResultsPanel({ questions, answers }) {
        return (
          <div className="result" aria-live="polite">
            <h2>Selections submitted</h2>
            <p>Your responses are listed below.</p>
            <ul>
              {questions.map((question) => {
                const selected = question.options
                  .filter((option) => answers[question.id]?.includes(option.value))
                  .map((option) => option.label);

                return (
                  <li key={question.id}>
                    <strong>{question.title}</strong>:{" "}
                    {selected.length ? selected.join(", ") : "No answers selected"}
                  </li>
                );
              })}
            </ul>
          </div>
        );
      }

      function QuizApp() {
        const [answers, setAnswers] = React.useState(
          Object.fromEntries(quizQuestions.map((question) => [question.id, []]))
        );
        const [submitted, setSubmitted] = React.useState(false);

        const toggleAnswer = (questionId, value) => {
          setAnswers((current) => {
            const choices = current[questionId] || [];
            const nextChoices = choices.includes(value)
              ? choices.filter((entry) => entry !== value)
              : [...choices, value];

            return {
              ...current,
              [questionId]: nextChoices,
            };
          });
        };

        const handleSubmit = (event) => {
          event.preventDefault();
          setSubmitted(true);
        };

        return (
          <main className="page-shell">
            <section className="quiz-card">
              <header className="hero">
                <span className="eyebrow">Interactive knowledge check</span>
                <h1>Computer Languages Quiz</h1>
                <p>
                  Explore a short multi-select quiz covering compiled languages, web
                  technologies, and type-safe languages.
                </p>
              </header>

              <form id="quiz-form" onSubmit={handleSubmit}>
                {quizQuestions.map((question, index) => (
                  <QuestionField
                    key={question.id}
                    question={question}
                    index={index}
                    selectedAnswers={answers[question.id]}
                    onToggle={toggleAnswer}
                  />
                ))}
              </form>

              <div className="actions">
                <span className="submit-note">Each question supports multiple answers.</span>
                <button className="submit-button" type="submit" form="quiz-form">
                  Submit Quiz
                </button>
              </div>

              {submitted ? <ResultsPanel questions={quizQuestions} answers={answers} /> : null}
            </section>
          </main>
        );
      }

      const root = ReactDOM.createRoot(document.getElementById("root"));
      root.render(<QuizApp />);
    </script>
  </body>
</html>
